(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-morality-p18-advanced"]={"id":"unit22-morality-p18-advanced","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"2-2단원 · 4. 줄 서기의 도덕","name":"18문단 · 심화 5지선다","level":"심화","desc":"한 문제에 해당 본문 1문단씩 읽어요.","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","parts":[{"name":"U22-42 · 선물이라는 비유","items":[{"paragraphCount":1,"readingLabel":"18문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 18문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 18문단]\n퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다. 말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다. 물론 좌석 수는 한정되어 있다. 정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다. 하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다. 본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다. 이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["비유의 사실화"],"id":"U22-42-S1","type":"mc","sent":"18문단의 내용과 맞는 설명은?","options":["글쓴이는 무료 공연을 도시가 스스로 얻는 판매 수익에 빗대었다.","무료 공연은 시민 모두가 함께 즐기는 축제다. 그래서 '도시가 스스로에게 주는 선물'에 비유했다.","선물이라는 표현은 암표상이 돈을 버는 사업이라는 뜻이다.","선물이라는 표현은 시민에게 실제 현금을 나누어 주었다는 뜻이다.","도시가 스스로에게 주는 선물이라는 말은 암표상이 극장에 선물했다는 뜻이다."],"answer":"무료 공연은 시민 모두가 함께 즐기는 축제다. 그래서 '도시가 스스로에게 주는 선물'에 비유했다.","why":"무료 공연은 시민들이 함께 즐기며 도시를 축하하는 행사예요. 시민이 함께 누리는 공연이어서 도시가 자신에게 주는 선물이라고 표현했어요.\n18문단에서 확인할 수 있어요.","choiceReviews":{"무료 공연은 시민 모두가 함께 즐기는 축제다. 그래서 '도시가 스스로에게 주는 선물'에 비유했다.":{"reason":"무료 공연은 시민들이 함께 즐기며 도시를 축하하는 행사예요. 시민이 함께 누리는 공연이어서 도시가 자신에게 주는 선물이라고 표현했어요.\n18문단에서 확인할 수 있어요.","edits":[]},"글쓴이는 무료 공연을 도시가 스스로 얻는 판매 수익에 빗대었다.":{"reason":"바르게 고치면: 글쓴이는 무료 공연을 도시가 스스로에게 주는 선물에 빗대었다.\n무료 공연은 시민들이 함께 즐기며 도시를 축하하는 행사예요. 시민이 함께 누리는 공연이어서 도시가 자신에게 주는 선물이라고 표현했어요.\n18문단에서 확인할 수 있어요.","edits":[{"start":16,"end":30,"before":"스스로 얻는 판매 수익에 ","after":"스스로에게 주는 선물에 "}]},"선물이라는 표현은 암표상이 돈을 버는 사업이라는 뜻이다.":{"reason":"바르게 고치면: 선물이라는 표현은 시민 모두가 함께 즐기는 축제라는 뜻이다.\n무료 공연은 시민들이 함께 즐기며 도시를 축하하는 행사예요. 시민이 함께 누리는 공연이어서 도시가 자신에게 주는 선물이라고 표현했어요.\n18문단에서 확인할 수 있어요.","edits":[{"start":10,"end":27,"before":"암표상이 돈을 버는 사업이라는 ","after":"시민 모두가 함께 즐기는 축제라는 "}]},"선물이라는 표현은 시민에게 실제 현금을 나누어 주었다는 뜻이다.":{"reason":"바르게 고치면: 선물이라는 표현은 무료 공연을 선물에 빗댄 말이다.\n무료 공연은 시민들이 함께 즐기며 도시를 축하하는 행사예요. 시민이 함께 누리는 공연이어서 도시가 자신에게 주는 선물이라고 표현했어요.\n18문단에서 확인할 수 있어요.","edits":[{"start":10,"end":35,"before":"시민에게 실제 현금을 나누어 주었다는 뜻이다.","after":"무료 공연을 선물에 빗댄 말이다."}]},"도시가 스스로에게 주는 선물이라는 말은 암표상이 극장에 선물했다는 뜻이다.":{"reason":"바르게 고치면: 도시가 스스로에게 주는 선물이라는 말은 시민들이 무료 공연을 함께 누린다는 뜻이다.\n무료 공연은 시민들이 함께 즐기며 도시를 축하하는 행사예요. 시민이 함께 누리는 공연이어서 도시가 자신에게 주는 선물이라고 표현했어요.\n18문단에서 확인할 수 있어요.","edits":[{"start":22,"end":37,"before":"암표상이 극장에 선물했다는 ","after":"시민들이 무료 공연을 함께 누린다는 "}]}},"pageSpecificReasons":true,"evidence":{"title":"선물이라는 비유","statement":"무료 공연은 시민 모두가 함께 즐기는 축제다. 그래서 '도시가 스스로에게 주는 선물'에 비유했다.","explanation":"무료 공연은 시민들이 함께 즐기며 도시를 축하하는 행사예요. 시민이 함께 누리는 공연이어서 도시가 자신에게 주는 선물이라고 표현했어요.\n18문단에서 확인할 수 있어요.","valid":["L18:1","L18:2"],"sources":[{"id":"L18","title":"줄 서기를 돈으로 살 수 있을까","label":"18문단","sentences":[{"id":"L18:1","text":"퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다.","paragraph":0,"memberIds":["L18:1"],"topic":"극장은 이 무료 공연을 모두의 축제, 시민들의 잔치로 여긴다."},{"id":"L18:2","text":"말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다.","paragraph":0,"memberIds":["L18:2"],"topic":"말하자면 도시가 시민들, 곧 자기 자신에게 주는 선물이다."},{"id":"L18:3","text":"물론 좌석 수는 한정되어 있다.","paragraph":0,"memberIds":["L18:3"],"topic":"물론 자리는 정해져 있다."},{"id":"L18:4","text":"정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다.","paragraph":0,"memberIds":["L18:4"],"topic":"그날 저녁에 모든 시민이 다 올 수는 없으니까."},{"id":"L18:5","text":"하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L18:5"],"topic":"하지만 극장이 원래 하려던 것(취지)은 돈이 있든 없든 누구나 똑같이 공짜로 공연을 보게 하는 것이다."},{"id":"L18:6","text":"본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다.","paragraph":0,"memberIds":["L18:6"],"topic":"원래 선물이어야 할 행사에서 입장료를 받거나 암표상이 돈을 벌게 놔두면, 그 목적과 어긋난다."},{"id":"L18:7","text":"이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","paragraph":0,"memberIds":["L18:7"],"topic":"그건 모두의 축제를 개인의 돈벌이 수단(사적 이익의 도구)으로 바꿔 버리는 일이다."}]}]},"editorSourceVersion":"55b41e2292936e98e1551fd38f4cb7d833c57da3b6d6047d0910d3e6ca5d17be"}]},{"name":"U22-43 · 한정된 좌석과 평등한 관람 취지","items":[{"paragraphCount":1,"readingLabel":"18문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 18문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 18문단]\n퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다. 말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다. 물론 좌석 수는 한정되어 있다. 정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다. 하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다. 본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다. 이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["조건"],"id":"U22-43-S1","type":"mc","sent":"18문단의 내용과 맞는 설명은?","options":["모든 시민이 동시에 공연을 볼 수 있을 만큼 좌석이 있다.","공연의 목적은 돈을 얼마나 낼 수 있는지에 따라 볼 기회를 주는 것이다.","좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다. 그래도 돈이 많든 적든 누구나 무료 공연을 볼 기회를 똑같이 주려는 것이다.","무료 공연은 비싼 값을 내는 순서대로 보게 하려는 공연이다.","무료 공연은 돈 많은 사람부터 보게 하려는 공연이다."],"answer":"좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다. 그래도 돈이 많든 적든 누구나 무료 공연을 볼 기회를 똑같이 주려는 것이다.","why":"좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","choiceReviews":{"좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다. 그래도 돈이 많든 적든 누구나 무료 공연을 볼 기회를 똑같이 주려는 것이다.":{"reason":"좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[]},"모든 시민이 동시에 공연을 볼 수 있을 만큼 좌석이 있다.":{"reason":"바르게 고치면: 좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다.\n좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[{"start":0,"end":3,"before":"모든 ","after":"좌석이 부족해 모든 "},{"start":17,"end":32,"before":"수 있을 만큼 좌석이 있다.","after":"수는 없다."}]},"공연의 목적은 돈을 얼마나 낼 수 있는지에 따라 볼 기회를 주는 것이다.":{"reason":"바르게 고치면: 공연의 목적은 돈을 얼마나 낼 수 있는지와 상관없이 볼 기회를 주는 것이다.\n좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[{"start":19,"end":27,"before":"있는지에 따라 ","after":"있는지와 상관없이 "}]},"무료 공연은 비싼 값을 내는 순서대로 보게 하려는 공연이다.":{"reason":"바르게 고치면: 무료 공연은 누구에게나 볼 기회를 똑같이 주려는 공연이다.\n좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[{"start":7,"end":28,"before":"비싼 값을 내는 순서대로 보게 하려는 ","after":"누구에게나 볼 기회를 똑같이 주려는 "}]},"무료 공연은 돈 많은 사람부터 보게 하려는 공연이다.":{"reason":"바르게 고치면: 무료 공연은 돈이 많든 적든 똑같이 볼 기회를 주려는 공연이다.\n좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[{"start":7,"end":24,"before":"돈 많은 사람부터 보게 하려는 ","after":"돈이 많든 적든 똑같이 볼 기회를 주려는 "}]}},"pageSpecificReasons":true,"evidence":{"title":"한정된 좌석과 평등한 관람 취지","statement":"좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다. 그래도 돈이 많든 적든 누구나 무료 공연을 볼 기회를 똑같이 주려는 것이다.","explanation":"좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","valid":["L18:3","L18:4","L18:5"],"sources":[{"id":"L18","title":"줄 서기를 돈으로 살 수 있을까","label":"18문단","sentences":[{"id":"L18:1","text":"퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다.","paragraph":0,"memberIds":["L18:1"],"topic":"극장은 이 무료 공연을 모두의 축제, 시민들의 잔치로 여긴다."},{"id":"L18:2","text":"말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다.","paragraph":0,"memberIds":["L18:2"],"topic":"말하자면 도시가 시민들, 곧 자기 자신에게 주는 선물이다."},{"id":"L18:3","text":"물론 좌석 수는 한정되어 있다.","paragraph":0,"memberIds":["L18:3"],"topic":"물론 자리는 정해져 있다."},{"id":"L18:4","text":"정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다.","paragraph":0,"memberIds":["L18:4"],"topic":"그날 저녁에 모든 시민이 다 올 수는 없으니까."},{"id":"L18:5","text":"하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L18:5"],"topic":"하지만 극장이 원래 하려던 것(취지)은 돈이 있든 없든 누구나 똑같이 공짜로 공연을 보게 하는 것이다."},{"id":"L18:6","text":"본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다.","paragraph":0,"memberIds":["L18:6"],"topic":"원래 선물이어야 할 행사에서 입장료를 받거나 암표상이 돈을 벌게 놔두면, 그 목적과 어긋난다."},{"id":"L18:7","text":"이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","paragraph":0,"memberIds":["L18:7"],"topic":"그건 모두의 축제를 개인의 돈벌이 수단(사적 이익의 도구)으로 바꿔 버리는 일이다."}]}]},"editorSourceVersion":"33fa6896915088d55159cb11f7e4a8a7a1afaae0dcee801bcc786945906fcebc"}]},{"name":"U22-44 · 입장료·암표와 공공 축제의 변질","items":[{"paragraphCount":1,"readingLabel":"18문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 18문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 18문단]\n퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다. 말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다. 물론 좌석 수는 한정되어 있다. 정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다. 하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다. 본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다. 이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["인과"],"id":"U22-44-S1","type":"mc","sent":"18문단의 내용과 맞는 설명은?","options":["입장료를 받거나 암표로 돈을 벌게 하면 시민에게 선물하려던 목적을 잘 이룰 수 있다.","암표상이 돈을 버는 일은 모든 시민에게 똑같은 기회를 주는 방법이다.","입장료 없이 무료로 제공하는 일도 돈을 받고 파는 일과 같다.","입장료를 받거나 암표로 돈을 벌게 하면 시민 모두의 축제가 개인의 돈벌이가 된다. 시민들에게 무료 공연을 선물하려던 목적에 어긋난다.","글쓴이는 암표상이 돈을 벌어도 시민이 함께하는 축제의 의미가 지켜진다고 본다."],"answer":"입장료를 받거나 암표로 돈을 벌게 하면 시민 모두의 축제가 개인의 돈벌이가 된다. 시민들에게 무료 공연을 선물하려던 목적에 어긋난다.","why":"무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","choiceReviews":{"입장료를 받거나 암표로 돈을 벌게 하면 시민 모두의 축제가 개인의 돈벌이가 된다. 시민들에게 무료 공연을 선물하려던 목적에 어긋난다.":{"reason":"무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[]},"입장료를 받거나 암표로 돈을 벌게 하면 시민에게 선물하려던 목적을 잘 이룰 수 있다.":{"reason":"바르게 고치면: 입장료를 받거나 암표로 돈을 벌게 하면 시민에게 선물하려던 목적에 어긋난다.\n무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[{"start":33,"end":47,"before":"목적을 잘 이룰 수 있다.","after":"목적에 어긋난다."}]},"암표상이 돈을 버는 일은 모든 시민에게 똑같은 기회를 주는 방법이다.":{"reason":"바르게 고치면: 암표상이 돈을 버는 일은 시민 모두를 위한 축제를 개인의 돈벌이로 바꾸는 일이다.\n무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[{"start":14,"end":38,"before":"모든 시민에게 똑같은 기회를 주는 방법이다.","after":"시민 모두를 위한 축제를 개인의 돈벌이로 바꾸는 일이다."}]},"입장료 없이 무료로 제공하는 일도 돈을 받고 파는 일과 같다.":{"reason":"바르게 고치면: 무료로 제공하는 일은 돈을 받고 파는 일과 다르다.\n무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[{"start":0,"end":7,"before":"입장료 없이 ","after":""},{"start":16,"end":19,"before":"일도 ","after":"일은 "},{"start":31,"end":34,"before":"같다.","after":"다르다."}]},"글쓴이는 암표상이 돈을 벌어도 시민이 함께하는 축제의 의미가 지켜진다고 본다.":{"reason":"바르게 고치면: 글쓴이는 암표상이 돈을 벌면 시민이 함께하는 축제의 의미가 훼손된다고 본다.\n무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","edits":[{"start":13,"end":17,"before":"벌어도 ","after":"벌면 "},{"start":34,"end":40,"before":"지켜진다고 ","after":"훼손된다고 "}]}},"pageSpecificReasons":true,"evidence":{"title":"입장료·암표와 공공 축제의 변질","statement":"입장료를 받거나 암표로 돈을 벌게 하면 시민 모두의 축제가 개인의 돈벌이가 된다. 시민들에게 무료 공연을 선물하려던 목적에 어긋난다.","explanation":"무료 공연의 목적은 시민들이 함께 즐기는 것이에요. 암표를 팔아 돈을 벌면 시민 모두를 위한 축제가 개인이 이익을 챙기는 일이 돼요.\n18문단에서 확인할 수 있어요.","valid":["L18:5","L18:6","L18:7"],"sources":[{"id":"L18","title":"줄 서기를 돈으로 살 수 있을까","label":"18문단","sentences":[{"id":"L18:1","text":"퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다.","paragraph":0,"memberIds":["L18:1"],"topic":"극장은 이 무료 공연을 모두의 축제, 시민들의 잔치로 여긴다."},{"id":"L18:2","text":"말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다.","paragraph":0,"memberIds":["L18:2"],"topic":"말하자면 도시가 시민들, 곧 자기 자신에게 주는 선물이다."},{"id":"L18:3","text":"물론 좌석 수는 한정되어 있다.","paragraph":0,"memberIds":["L18:3"],"topic":"물론 자리는 정해져 있다."},{"id":"L18:4","text":"정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다.","paragraph":0,"memberIds":["L18:4"],"topic":"그날 저녁에 모든 시민이 다 올 수는 없으니까."},{"id":"L18:5","text":"하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L18:5"],"topic":"하지만 극장이 원래 하려던 것(취지)은 돈이 있든 없든 누구나 똑같이 공짜로 공연을 보게 하는 것이다."},{"id":"L18:6","text":"본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다.","paragraph":0,"memberIds":["L18:6"],"topic":"원래 선물이어야 할 행사에서 입장료를 받거나 암표상이 돈을 벌게 놔두면, 그 목적과 어긋난다."},{"id":"L18:7","text":"이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","paragraph":0,"memberIds":["L18:7"],"topic":"그건 모두의 축제를 개인의 돈벌이 수단(사적 이익의 도구)으로 바꿔 버리는 일이다."}]}]},"editorSourceVersion":"e5dac5f2c1ad59178c4dfb7efffc9c920c5fbb1a761866487a7d1e3d0ecb2c1e"}]}],"readingBlock":"morality","readingChunk":"p18","cat":"2-2단원"};})(window);
